//! Bounded Sixel raster decoding and iTerm inline-image to Kitty placement bridge.
use base64::{Engine as _, engine::general_purpose::STANDARD as B64};
use libghostty_vt::Terminal;
const MAX_SIDE: usize = 8192;
const MAX_PIXELS: usize = 16 * 1024 * 1024;
const MAX_ENCODED: usize = 32 * 1024 * 1024;
// Anonymous images generated by the Sixel/iTerm bridge use this placement ID
// so text erasure can remove them without deleting application-owned Kitty
// images. Checkpoints preserve placement IDs across reconnects.
const INLINE_PLACEMENT: u32 = u32::MAX;
#[derive(Default)]
pub struct Images {
    multipart: Option<(String, String)>,
}
impl Images {
    pub fn iterm(
        &mut self,
        packet: &str,
        vt: &mut Terminal<'_, '_>,
        cell: (u32, u32),
        decode: impl FnOnce(&[u8]) -> Option<(Vec<u8>, u32, u32)>,
    ) {
        if let Some(value) = packet.strip_prefix("MultipartFile=") {
            self.multipart = Some((value.into(), String::new()));
            return;
        }
        if let Some(part) = packet.strip_prefix("FilePart=") {
            if let Some((_, data)) = &mut self.multipart {
                if data.len() + part.len() <= MAX_ENCODED {
                    data.push_str(part);
                } else {
                    self.multipart = None;
                }
            }
            return;
        }
        let (metadata, payload) = if packet == "FileEnd" {
            let Some(parts) = self.multipart.take() else {
                return;
            };
            parts
        } else if let Some(file) = packet.strip_prefix("File=") {
            let Some((a, b)) = file.split_once(':') else {
                return;
            };
            (a.into(), b.into())
        } else {
            return;
        };
        let meta: std::collections::HashMap<_, _> = metadata
            .split(';')
            .filter_map(|s| s.split_once('='))
            .collect();
        if meta.get("inline") != Some(&"1") || payload.len() > MAX_ENCODED {
            return;
        }
        let Ok(data) = B64.decode(payload) else {
            return;
        };
        let Some((source_w, source_h)) = dimensions(&data) else {
            return;
        };
        if source_w == 0
            || source_h == 0
            || source_w > MAX_SIDE
            || source_h > MAX_SIDE
            || source_w.saturating_mul(source_h) > MAX_PIXELS
        {
            return;
        }
        let Some((png, w, h)) = decode(&data) else {
            return;
        };
        if w as usize * h as usize > MAX_PIXELS {
            return;
        }
        let width = dimension(
            meta.get("width").copied(),
            cell.0,
            vt.cols().unwrap_or(80) as u32,
        );
        let height = dimension(
            meta.get("height").copied(),
            cell.1,
            vt.rows().unwrap_or(24) as u32,
        );
        let (mut dw, mut dh) = match (width, height) {
            (Some(wd), Some(hd)) => (wd, hd),
            (Some(wd), None) => (wd, ((h as u64 * wd as u64) / w as u64).max(1) as u32),
            (None, Some(hd)) => (((w as u64 * hd as u64) / h as u64).max(1) as u32, hd),
            _ => (w, h),
        };
        if meta.get("preserveAspectRatio") != Some(&"0") && width.is_some() && height.is_some() {
            let scale = (dw as f64 / w as f64).min(dh as f64 / h as f64);
            dw = (w as f64 * scale).max(1.) as u32;
            dh = (h as f64 * scale).max(1.) as u32;
        }
        place(vt, &png, dw, dh, cell);
    }
}
fn dimension(value: Option<&str>, cell: u32, cells: u32) -> Option<u32> {
    let value = value?;
    let n = if let Some(s) = value.strip_suffix("px") {
        s.parse::<u32>().ok()?
    } else if let Some(s) = value.strip_suffix('%') {
        s.parse::<u32>()
            .ok()?
            .saturating_mul(cells)
            .saturating_mul(cell)
            / 100
    } else {
        value.parse::<u32>().ok()?.saturating_mul(cell)
    };
    Some(n.clamp(1, MAX_SIDE as u32))
}
pub fn place(vt: &mut Terminal<'_, '_>, png: &[u8], w: u32, h: u32, cell: (u32, u32)) {
    let data = B64.encode(png);
    let cols = w.div_ceil(cell.0.max(1)).max(1);
    let rows = h.div_ceil(cell.1.max(1)).max(1);
    for (i, chunk) in data.as_bytes().chunks(4096).enumerate() {
        let more = usize::from((i + 1) * 4096 < data.len());
        let header = if i == 0 {
            format!("\x1b_Ga=T,f=100,t=d,q=2,p={INLINE_PLACEMENT},c={cols},r={rows},m={more};")
        } else {
            format!("\x1b_Gm={more};")
        };
        vt.vt_write(header.as_bytes());
        vt.vt_write(chunk);
        vt.vt_write(b"\x1b\\");
    }
}

/// Sixel/iTerm images belong to the text area they were printed into. Kitty
/// placements have a different lifetime, so the bridge must honor text erase
/// commands explicitly (notably fzf's line-by-line preview cleanup).
pub fn erase(vt: &mut Terminal<'_, '_>, command: u8, count: u32) {
    use libghostty_vt::{kitty::graphics::PlacementIterator, terminal::PointSpace};
    let remove = (|| -> libghostty_vt::error::Result<Vec<u32>> {
        let (cx, cy) = (u32::from(vt.cursor_x()?), u32::from(vt.cursor_y()?));
        let active_top = vt.total_rows()?.saturating_sub(usize::from(vt.rows()?)) as u32;
        let cursor = (active_top + cy, cx);
        let Some(graphics) = vt.kitty_graphics()? else { return Ok(Vec::new()) };
        let mut iterator = PlacementIterator::new()?;
        let mut iter = iterator.update(&graphics)?;
        let mut ids = Vec::new();
        while let Some(p) = iter.next() {
            if p.placement_id()? != INLINE_PLACEMENT || p.is_virtual()? {
                continue;
            }
            let id = p.image_id()?;
            let Some(image) = graphics.image(id) else {
                continue;
            };
            let Some(rect) = p.rect(&image, vt)? else { continue };
            let Some(start) = vt.point_from_grid_ref(&rect.start(), PointSpace::Screen)? else {
                continue;
            };
            let Some(end) = vt.point_from_grid_ref(&rect.end(), PointSpace::Screen)? else {
                continue;
            };
            let hit = match (command, count) {
                (b'J', 0) => (end.y, u32::from(end.x)) >= cursor,
                (b'J', 1) => end.y >= active_top && (start.y, u32::from(start.x)) <= cursor,
                (b'J', 2) => end.y >= active_top,
                (b'J', 3) => start.y < active_top,
                (b'K', 0) => start.y <= cursor.0 && end.y >= cursor.0 && u32::from(end.x) >= cx,
                (b'K', 1) => start.y <= cursor.0 && end.y >= cursor.0 && u32::from(start.x) <= cx,
                (b'K', 2) => start.y <= cursor.0 && end.y >= cursor.0,
                (b'X', n) => {
                    start.y <= cursor.0
                        && end.y >= cursor.0
                        && u32::from(end.x) >= cx
                        && u32::from(start.x) < cx.saturating_add(n.max(1))
                }
                _ => false,
            };
            if hit {
                ids.push(id);
            }
        }
        Ok(ids)
    })()
    .unwrap_or_default();
    for id in remove {
        vt.vt_write(format!("\x1b_Ga=d,d=I,i={id},q=2;\x1b\\").as_bytes());
    }
}
fn numbers(data: &[u8], i: &mut usize) -> Vec<usize> {
    let mut result = vec![0usize];
    while let Some(&b) = data.get(*i) {
        if b.is_ascii_digit() {
            let last = result.last_mut().unwrap();
            *last = last.saturating_mul(10).saturating_add((b - b'0') as usize);
        } else if b == b';' && result.len() < 8 {
            result.push(0);
        } else {
            break;
        }
        *i += 1;
    }
    result
}
fn scan(data: &[u8], mut paint: impl FnMut(usize, usize, u8, [u8; 4])) -> Option<(usize, usize)> {
    let (mut x, mut y, mut width, mut height, mut i) = (0usize, 0usize, 0usize, 0usize, 0usize);
    let mut palette = [[0, 0, 0, 255]; 256];
    for (i, c) in palette.iter_mut().enumerate() {
        let v = (i % 16 * 17) as u8;
        *c = [v, v, v, 255];
    }
    let defaults = [
        [0, 0, 0],
        [51, 51, 204],
        [204, 35, 35],
        [51, 204, 51],
        [204, 51, 204],
        [51, 204, 204],
        [204, 204, 204],
        [119, 119, 119],
        [68, 68, 68],
        [86, 86, 153],
        [153, 68, 68],
        [86, 153, 86],
        [153, 86, 153],
        [86, 153, 153],
        [153, 153, 86],
        [204, 204, 204],
    ];
    for (i, c) in defaults.iter().enumerate() {
        palette[i] = [c[0], c[1], c[2], 255];
    }
    let mut color = [0, 255, 0, 255];
    let mut work = 0usize;
    while i < data.len() {
        let b = data[i];
        i += 1;
        let mut repeat = 1;
        let mut value = b;
        match b {
            b'"' => {
                let n = numbers(data, &mut i);
                if n.len() >= 4 {
                    width = width.max(n[2]);
                    height = height.max(n[3]);
                }
                continue;
            }
            b'#' => {
                let n = numbers(data, &mut i);
                let index = n[0].min(255);
                if n.len() >= 5 {
                    if n[1] == 2 {
                        palette[index] = [
                            (n[2].min(100) * 255 / 100) as u8,
                            (n[3].min(100) * 255 / 100) as u8,
                            (n[4].min(100) * 255 / 100) as u8,
                            255,
                        ];
                    } else if n[1] == 1 {
                        let h = ((n[2] as f64 + 240.) % 360.) / 60.;
                        let l = n[3].min(100) as f64 / 100.;
                        let s = n[4].min(100) as f64 / 100.;
                        let c = (1. - (2. * l - 1.).abs()) * s;
                        let x = c * (1. - (h % 2. - 1.).abs());
                        let m = l - c / 2.;
                        let rgb = match h as u8 {
                            0 => [c, x, 0.],
                            1 => [x, c, 0.],
                            2 => [0., c, x],
                            3 => [0., x, c],
                            4 => [x, 0., c],
                            _ => [c, 0., x],
                        };
                        palette[index] = [
                            ((rgb[0] + m) * 255.) as u8,
                            ((rgb[1] + m) * 255.) as u8,
                            ((rgb[2] + m) * 255.) as u8,
                            255,
                        ];
                    }
                }
                color = palette[index];
                continue;
            }
            b'$' => {
                x = 0;
                continue;
            }
            b'-' => {
                x = 0;
                y = y.checked_add(6)?;
                if y > MAX_SIDE {
                    return None;
                }
                continue;
            }
            b'!' => {
                repeat = numbers(data, &mut i)[0].max(1);
                value = *data.get(i)?;
                i += 1;
            }
            _ => {}
        }
        if !(b'?'..=b'~').contains(&value) {
            continue;
        }
        if repeat > MAX_SIDE || x + repeat > MAX_SIDE || y + 6 > MAX_SIDE {
            return None;
        }
        work = work.checked_add(repeat * 6)?;
        if work > MAX_PIXELS * 4 {
            return None;
        }
        for col in x..x + repeat {
            paint(col, y, value - b'?', color);
        }
        x += repeat;
        width = width.max(x);
        height = height.max(y + 6);
        if width > MAX_SIDE || height > MAX_SIDE || width.checked_mul(height)? > MAX_PIXELS {
            return None;
        }
    }
    (width > 0
        && height > 0
        && width <= MAX_SIDE
        && height <= MAX_SIDE
        && width.checked_mul(height)? <= MAX_PIXELS)
        .then_some((width, height))
}
pub fn sixel(data: &[u8]) -> Option<(Vec<u8>, u32, u32)> {
    let q = data.iter().position(|&b| b == b'q')?;
    if !data[..q].iter().all(|b| b.is_ascii_digit() || *b == b';') {
        return None;
    }
    let transparent = data[..q].split(|&b| b == b';').nth(1) == Some(b"1".as_slice());
    let body = &data[q + 1..];
    let (w, h) = scan(body, |_, _, _, _| {})?;
    let mut pixels = vec![0u8; w * h * 4];
    if !transparent {
        for pixel in pixels.chunks_exact_mut(4) {
            pixel[3] = 255;
        }
    }
    scan(body, |x, y, b, color| {
        for bit in 0..6 {
            if b & (1 << bit) != 0 && x < w && y + bit < h {
                let offset = ((y + bit) * w + x) * 4;
                pixels[offset..offset + 4].copy_from_slice(&color);
            }
        }
    })?;
    let mut png = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut png, w as u32, h as u32);
        encoder.set_color(png::ColorType::Rgba);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .ok()?
            .write_image_data(&pixels)
            .ok()?;
    }
    Some((png, w as u32, h as u32))
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn sixel_bounds_and_pixels() {
        let (png, w, h) = sixel(b"0;1q\"1;1;2;6#1;2;100;0;0!2~").unwrap();
        assert_eq!((w, h), (2, 6));
        let mut decoder = png::Decoder::new(std::io::Cursor::new(png.as_slice()))
            .read_info()
            .unwrap();
        let mut data = vec![0; decoder.output_buffer_size().unwrap()];
        decoder.next_frame(&mut data).unwrap();
        assert_eq!(&data[..8], &[255, 0, 0, 255, 255, 0, 0, 255]);
        assert!(sixel(b"q!999999999~").is_none());
        assert!(sixel(b"q\"1;1;999999;999999").is_none());
    }
}

fn dimensions(data: &[u8]) -> Option<(usize, usize)> {
    if data.starts_with(b"\x89PNG\r\n\x1a\n") {
        return Some((
            u32::from_be_bytes(data.get(16..20)?.try_into().ok()?) as usize,
            u32::from_be_bytes(data.get(20..24)?.try_into().ok()?) as usize,
        ));
    }
    if data.starts_with(b"BM") {
        return Some((
            i32::from_le_bytes(data.get(18..22)?.try_into().ok()?).unsigned_abs() as usize,
            i32::from_le_bytes(data.get(22..26)?.try_into().ok()?).unsigned_abs() as usize,
        ));
    }
    if data.starts_with(b"\xff\xd8") {
        let mut i = 2;
        while i + 4 <= data.len() {
            if data[i] != 255 {
                return None;
            }
            i += 1;
            while data.get(i) == Some(&255) {
                i += 1;
            }
            let marker = *data.get(i)?;
            i += 1;
            if matches!(marker, 0xd8 | 0xd9 | 0x01 | 0xd0..=0xd7) {
                continue;
            }
            let length = u16::from_be_bytes(data.get(i..i + 2)?.try_into().ok()?) as usize;
            if length < 2 || i + length > data.len() {
                return None;
            }
            if matches!(marker,0xc0..=0xc3|0xc5..=0xc7|0xc9..=0xcb|0xcd..=0xcf) {
                return Some((
                    u16::from_be_bytes(data.get(i + 5..i + 7)?.try_into().ok()?) as usize,
                    u16::from_be_bytes(data.get(i + 3..i + 5)?.try_into().ok()?) as usize,
                ));
            }
            i += length;
        }
    }
    if data.starts_with(b"RIFF") && data.get(8..12) == Some(b"WEBP") {
        let le24 = |start| -> Option<usize> {
            let s = data.get(start..start + 3)?;
            Some(s[0] as usize | (s[1] as usize) << 8 | (s[2] as usize) << 16)
        };
        if data.get(12..16) == Some(b"VP8X") {
            return Some((le24(24)? + 1, le24(27)? + 1));
        }
        if data.get(12..16) == Some(b"VP8L") {
            let bits = u32::from_le_bytes(data.get(21..25)?.try_into().ok()?);
            return Some((
                (bits & 0x3fff) as usize + 1,
                ((bits >> 14) & 0x3fff) as usize + 1,
            ));
        }
        if data.get(12..16) == Some(b"VP8 ") && data.get(23..26) == Some(b"\x9d\x01\x2a") {
            return Some((
                (u16::from_le_bytes(data.get(26..28)?.try_into().ok()?) & 0x3fff) as usize,
                (u16::from_le_bytes(data.get(28..30)?.try_into().ok()?) & 0x3fff) as usize,
            ));
        }
    }
    None
}
